+		if (!cgid)
+			continue;
+		/* racy against slot reuse but weight is advisory and self-corrects */
+		w = read_cgroup_weight(cgid);
+		if (w && w != qa->sub_sched_ctxs[i].weight) {
+			qa->sub_sched_ctxs[i].weight = w;
+			changed = true;
+		}
+	}
+	return changed;
